                ConversionSentence(24, "The motion before the house demands rigorous critical analysis.", "ایوان کے سامنے پیش کردہ قرارداد گہرے تجزیے کی متقاضی ہے۔", "Aaiwan ke samnay pesh qaraardaad gehray jaizay ki talabgaar hai."),
                ConversionSentence(25, "I propose a balanced synthesis that incorporates both viewpoints.", "میں ایک ایسا متوازن حل پیش کرتا ہوں جو دونوں آراء کا احاطہ کرے۔", "Mein aik aisa motadil hal pesh karta hoon jo dono ko jorray."),
                ConversionSentence(26, "Passionate conviction must always be guided by rational reason.", "پرجوش جذبات کو ہمیشہ عقل اور منطق کے تابع ہونا چاہیے۔", "Purjosh jazbaat ko aql aur mantiq ke tehat hona chahiye."),
                ConversionSentence(27, "Let us conclude our arguments within the assigned two-minute rebuttal.", "آئیں اپنے دلائل دو منٹ کے دیے گئے وقت میں مکمل کریں۔", "Aayein apne dalaail do minute ke waqt mein mukammal karein."),
                ConversionSentence(28, "The purpose of debate is not ego victory, but illumination of truth.", "بحث کا مقصد جیتنا نہیں بلکہ حق اور سچائی کو واضح کرنا ہے۔", "Behas ka maqsad jeetna nahi balkay sach ko wazeh karna hai."),
                ConversionSentence(29, "I commend the honorable opposition for their sharp analytical points.", "میں مخالف پینل کے شاندار اور مدلل نکات کی تعریف کرتا ہوں۔", "Mein mukhalif panel ke shandar nukat ki tareef karta hoon."),
                ConversionSentence(30, "Intellectual humility is the first prerequisite for genuine learning.", "علمی عاجزی ہی سچی دانائی اور سیکھنے کی پہلی شرط ہے۔", "Ilmi aajzi hi sachi danai aur seekhnay ki pehli shart hai."),
                ConversionSentence(31, "What are the ethical implications of genetic engineering in medicine?", "طب میں جینیاتی تبدیلی کے اخلاقی تقاضے کیا ہیں؟", "Tibb mein genetic tabdeeli ke ikhlaaqi taqazay kya hain?"),
                ConversionSentence(32, "We must protect free speech while condemning malicious slander.", "ہمیں آزادی اظہار کا دفاع کرتے ہوئے جھوٹ اور بہتان کی مذمت کرنی چاہیے۔", "Azaadi-e-izhaar ke sath bohtaan ki muzammat karein."),
                ConversionSentence(33, "The evidence overwhelmingly supports the urgent need for environmental reform.", "شواہد فوری طور پر ماحولیاتی اصلاحات کی ضرورت کو ثابت کرتے ہیں۔", "Shawahid fauri tor par maholiyaati islaah ki zaroorat batatay hain."),
                ConversionSentence(34, "Let us not derail the core debate into secondary trivial matters.", "آئیں بنیادی بحث کو چھوڑ کر غیر ضروری باتوں میں نہ الجھیں۔", "Aayein ahem behas chorr kar ghair zaroori baton mein na uljhein."),
                ConversionSentence(35, "Clear logic and sound premise lead to inevitable conclusions.", "صاف منطق اور درست بنیاد ہمیشہ صحیح نتائج تک پہنچاتی ہے۔", "Saaf mantiq aur durust bunyad sahih nataij tak pohanchati hai."),
                ConversionSentence(36, "I stand firmly in support of universal quality education for all children.", "میں ہر بچے کے لیے معیاری اور مفت تعلیم کی پرزور حمایت کرتا ہوں۔", "Mein har bachay ke liye meyaari taleem ki purzor himayat karta hoon."),
                ConversionSentence(37, "Economic prosperity cannot be separated from social justice.", "معاشی خوشحالی کو سماجی انصاف سے الگ نہیں کیا جا سکتا۔", "Maashi khush-haali ko samaji insaaf se alag nahi kiya ja sakta."),
                ConversionSentence(38, "Let us weigh the long-term benefits against immediate short-term costs.", "آئیں فوری اخراجات کے مقابلے میں دیرپا فوائد کا موازنہ کریں۔", "Aayein fori ikhrajat ke muqablay mein taweel fawaid dekhein."),
                ConversionSentence(39, "The strength of an argument lies in its proof, not in loud volume.", "دلیل کی طاقت آواز کی بلندی میں نہیں بلکہ ثبوت کے وزن میں ہے۔", "Daleel ki taaqat aawaz mein nahi balkay saboot ke wazan mein hai."),
                ConversionSentence(40, "Thoughtful disagreement sharpens the intellect and broadens wisdom.", "شائستہ اختلاف عقل کو جلا بخشتا ہے اور سوچ کو وسیع کرتا ہے۔", "Shaista ikhtilaaf aql ko tez karta hai aur soch ko wasee karta hai."),
                ConversionSentence(41, "I invite the judges to critically evaluate both sides of the motion.", "میں ججز سے درخواست کرتا ہوں کہ وہ دونوں اطراف کے دلائل کا جائزہ لیں۔", "Mein judges se kehta hoon ke dono atraaf ke dalaail parkhein."),
                ConversionSentence(42, "We must address structural inequalities rather than temporary symptoms.", "ہمیں عارضی علامات کے بجائے بنیادی ناانصافیوں کو ختم کرنا ہوگا۔", "Humein bunyadi na-insafiyon ko khatam karna hoga."),
                ConversionSentence(43, "Respectful dialogue builds bridges across deep ideological divides.", "شائستہ مکالمہ مختلف نظریات رکھنے والوں کے درمیان پل بناتا ہے۔", "Shaista mukalma mukhtalif nazriyaat walon ko jorta hai."),
                ConversionSentence(44, "Critical thinking enables citizens to discern fact from propaganda.", "تنقیدی سوچ انسان کو سچائی اور پروپیگنڈے میں فرق سکھاتی ہے۔", "Tanqeedi soch insaan ko sach aur jhoot mein farq sikhati hai."),
                ConversionSentence(45, "Let justice, empathy, and logic guide our collective societal decisions.", "ہمارے تمام اجتماعی فیصلے انصاف، ہمدردی اور عقل کی بنیاد پر ہوں۔", "Hamare tamam faislay insaaf aur aql ki bunyad par hon."),
                ConversionSentence(46, "I thank the adjudicators, timekeeper, and the audience for their presence.", "میں ججز، ٹائم کیپر اور حاضرین کا تہہ دل سے شکریہ ادا کرتا ہوں۔", "Mein judges aur hazireen ka teh-e-dil se shukriya ada karta hoon."),
                ConversionSentence(47, "May intellectual honesty always prevail in every academic forum.", "اللہ کرے ہر علمی مجلس میں ہمیشہ سچائی اور دیانت داری کا بول بالا ہو!", "Allah karay har ilmi mehfil mein dyanat-dari ka bol baala ho!"),
                ConversionSentence(48, "Divergent viewpoints, when handled respectfully, enrich human culture.", "مختلف آراء باہمی احترام کے ساتھ انسانی تہذیب کو نکھارتی ہیں۔", "Mukhtalif aara ihtiram ke sath tehzeeb ko nikharti hain."),
                ConversionSentence(49, "Thank you for an enriching, challenging, and deeply inspiring debate.", "ایک شاندار، فکری اور پرتاثیر مباحثے کے لیے آپ کا بے حد شکریہ۔", "Aik shandar aur ilmi mubahisay ke liye aap ka bohat shukriya."),
                ConversionSentence(50, "May our pursuit of truth guide us toward enlightenment and peace!", "اللہ کرے سچ کی تلاش ہمیں ہمیشہ علم اور امن کی راہ دکھائے!", "Allah karay sach ki talash humein roshni aur aman ki raah dikhaye!")
            )),
