            ConversionTopic(43, "Mental Health & Stress Relief", "ذہنی صحت اور سکون", "spa", "Mindfulness, anxiety relief, gratitude, inner peace, and self-care.", listOf(
                ConversionSentence(1, "Mental health is just as crucial as physical bodily wellbeing.", "ذہنی صحت اتنی ہی ضروری ہے جتنی کہ جسمانی تندرستی۔", "Zehni sehat utni hi zaroori hai jitni jismani tandrusti."),
                ConversionSentence(2, "Taking deep, slow diaphragmatic breaths instantly lowers cortisol levels.", "گہرے اور آہستہ سانس لینا ذہنی دباؤ کے ہارمونز کو فوراً کم کرتا ہے۔", "Gehray saans lena zehni dabao ko fori kam karta hai."),
                ConversionSentence(3, "It is completely okay to seek professional therapy when feeling overwhelmed.", "جب بوجھ زیادہ لگے تو ماہر نفسیات سے مشورہ لینا بالکل درست ہے۔", "Jab bojh zyada lagay to expert se mashwara lena theek hai."),
                ConversionSentence(4, "Practicing daily morning gratitude rewires the brain towards optimism.", "روزانہ صبح شکر گزاری کی عادت ذہن کو پرامید اور خوش رکھتی ہے۔", "Rozana subah shukr-guzari zehan ko pur-umeed rakhti hai."),
                ConversionSentence(5, "Set healthy emotional boundaries to protect your peace of mind.", "اپنے ذہنی سکون کے تحفظ کے لیے ضروری حدیں قائم کریں۔", "Apne zehni sukoon ke tahaffuz ke liye zaroori hudood banayein."),
                ConversionSentence(6, "A fifteen-minute walk in nature lowers anxiety and clears mental fog.", "قدرت میں پندرہ منٹ کی واک گھبراہٹ کو دور کر کے ذہن صاف کرتی ہے۔", "Qudrat mein 15 minute ki walk zehan ko saaf karti hai."),
                ConversionSentence(7, "Do not bottle up heavy emotions; talk to a trusted friend or mentor.", "اپنے دکھ اور بوجھ کو اکیلے مت سہہیں، کسی مخلص سے بات کریں۔", "Apne dukh ko akele mat sahein, kisi mukhlis se baat karein."),
                ConversionSentence(8, "Adequate, restful eight-hour sleep is medicine for the nervous system.", "آٹھ گھنٹے کی پرسکون نیند اعصابی نظام کے لیے بہترین دوا ہے۔", "Aath ghantay ki pursukoon neend a'asaab ke liye dawa hai."),
                ConversionSentence(9, "Mindfulness is being present in the moment without harsh self-judgment.", "مائنڈفل نیس کا مطلب خود پر تنقید کیے بغیر حال میں جینا ہے۔", "Mindfulness ka matlab haal mein pursukoon rehna hai."),
                ConversionSentence(10, "You are stronger than your anxious thoughts; this difficulty will pass.", "آپ اپنی پریشانیوں سے زیادہ طاقتور ہیں؛ یہ وقت بھی گزر جائے گا۔", "Aap apni pareshaniyon se taqatwar hain; yeh waqt guzar jaye ga."),
                ConversionSentence(11, "How do you manage overwhelming workload stress during peak deadlines?", "آپ کام کے زیادہ دباؤ اور ڈیڈ لائنز کے دوران سکون کیسے رکھتے ہیں؟", "Aap kaam ke dabao mein sukoon kaisay rakhtay hain?"),
                ConversionSentence(12, "Break daunting large projects into tiny, manageable daily steps.", "بڑے اور مشکل کاموں کو چھوٹے چھوٹے روزانہ کے حصوں میں بانٹ لیں۔", "Baray kamon ko chhotay chhotay hisson mein baant lein."),
                ConversionSentence(13, "Avoid comparing your life journey with others' curated social media.", "اپنی زندگی کا موازنہ دوسروں کی سوشل میڈیا تصویروں سے مت کریں۔", "Apni zindagi ka mawazna social media se mat karein."),
                ConversionSentence(14, "Writing your worries in a private journal takes the weight off your chest.", "اپنی پریشانیاں ڈائری میں لکھ لینا دل کا بوجھ ہلکا کر دیتا ہے۔", "Apni pareshaniyan diary mein likhna dil ka bojh halka karta hai."),
                ConversionSentence(15, "Gentle stretching and yoga relieve tension stored in neck and shoulders.", "ہلکی ورزش گردن اور کندھوں کا کھنچاؤ دور کرتی ہے۔", "Halki warzish gardan aur kandhon ka khinchao door karti hai."),
                ConversionSentence(16, "Listen to soothing nature sounds like flowing rivers and falling rain.", "بہتے پانی اور بارش کی پرسکون آوازیں سن کر اعصاب پرسکون کریں۔", "Behtay paani aur barish ki pursukoon aawazein sunein."),
                ConversionSentence(17, "It is not a weakness to admit that you need rest and recovery.", "تھکن کا اعتراف کر کے آرام کرنا کمزوری نہیں بلکہ دانشمندی ہے۔", "Thakan ka aiteeraaf kar ke aaram karna aqalmandi hai."),
                ConversionSentence(18, "Practice the 4-7-8 breathing exercise to fall asleep peacefully.", "پرسکون نیند کے لیے چار سیکنڈ سانس لیں اور آٹھ سیکنڈ میں نکالیں۔", "Pursukoon neend ke liye gehray saans ki mashq karein."),
                ConversionSentence(19, "Unplug from electronic screens at least one hour before bedtime.", "سونے سے کم از کم ایک گھنٹہ پہلے تمام موبائل اسکرینیں بند کر دیں۔", "Sonay se aik ghanta pehle screens band kar dein."),
                ConversionSentence(20, "Be as kind and forgiving to yourself as you would to a dear friend.", "اپنے ساتھ بھی اتنی ہی نرمی اور شفقت برتیں جتنی دوست کے ساتھ۔", "Apne sath bhi utni hi narmi bartein jitni dost ke sath."),
                ConversionSentence(21, "Spiritual prayer and dhikr instill deep serenity within the troubled soul.", "نماز، دعا اور ذکرِ الٰہی بے چین روح کو حقیقی سکون بخشتے ہیں۔", "Namaz, dua aur zikr-e-Ilahi rooh ko sukoon bakhshtay hain."),
                ConversionSentence(22, "Normalize talking openly about anxiety, depression, and mental health.", "ذہنی دباؤ اور ڈپریشن پر کھلی اور ہمدردانہ گفتگو کو رواج دیں۔", "Zehni dabao aur depression par khuli baat cheet ko aam karein."),
                ConversionSentence(23, "Laughter with cherished family releases uplifting endorphin chemicals.", "پیاروں کے ساتھ کھلکھلا کر ہنسنا جسم میں خوشی کے ہارمونز بناتا ہے۔", "Pyaron ke sath hansna jism mein khushi ke hormones banata hai."),
                ConversionSentence(24, "Drink warm herbal chamomile or mint tea to soothe nervous jitters.", "اعصابی بے چینی دور کرنے کے لیے پودینے یا بابونہ کا قہوہ پئیں۔", "Be-chaini door karne ke liye podeenay ka qahwa piyein."),
                ConversionSentence(25, "Physical exercise is one of the most effective natural antidepressants.", "روزانہ کی ورزش ڈپریشن کے خلاف قدرت کی بہترین دوا ہے۔", "Rozana ki warzish depression ke khilaf behtareen dawa hai."),
                ConversionSentence(26, "Celebrate minor daily victories and do not dwell on minor mistakes.", "اپنی چھوٹی چھوٹی کامیابیوں کو سراہیں اور غلطیوں کو بھول جائیں۔", "Apni chhoti kamyabiyon ko sarahein aur ghalti bhool jayein."),
                ConversionSentence(27, "You do not have to carry the whole world's problems on your shoulders.", "آپ پر پوری دنیا کا بوجھ اکیلے اٹھانے کی ذمہ داری نہیں ہے۔", "Aap par poori dunya ka bojh akele uthanay ka farz nahi hai."),
                ConversionSentence(28, "Give yourself permission to pause, rest, recharge, and breathe deeply.", "خود کو رکنے، سانس لینے اور توانائی بحال کرنے کا موقع دیں۔", "Khud ko ruknay, saans lenay aur aaram ka mauqa dein."),
                ConversionSentence(29, "Surround yourself with compassionate, positive, and supportive souls.", "اپنے اردگرد مخلص، مثبت اور محبت کرنے والے لوگوں کو رکھیں۔", "Apne gird mukhlis aur musbat logon ko rakhein."),
                ConversionSentence(30, "A calm mind creates clear thinking and effective problem-solving.", "پرسکون ذہن ہی صاف سوچ اور مسائل کا بہترین حل نکالتا ہے۔", "Pursukoon zehan hi saaf soch aur hal nikaalta hai."),
                ConversionSentence(31, "Release the urge to control what is entirely outside your hands.", "ان باتوں کی فکر چھوڑ دیں جو آپ کے اختیار میں بالکل نہیں ہیں۔", "Un baton ki fikr chorr dein jo aap ke bas mein nahi hain."),
                ConversionSentence(32, "Focus your precious energy only on what you can change today.", "اپنی توانائی صرف ان کاموں پر لگائیں جو آپ آج بدل سکتے ہیں۔", "Apni tawanaai sirf un kamon par lagayein jo aap badal saktay hain."),
                ConversionSentence(33, "Spend time in quiet reflection away from urban noise and traffic.", "شہر کے شور سے دور کچھ وقت تنہائی اور غور و فکر میں گزاریں۔", "Shehar ke shor se door kuch waqt tanhai mein guzarein."),
                ConversionSentence(34, "Self-care is not selfish; it is essential to care for others well.", "اپنا خیال رکھنا خود غرضی نہیں بلکہ دوسروں کی خدمت کے لیے لازمی ہے۔", "Apna khayal rakhna doosron ki khidmat ke liye laazmi hai."),
                ConversionSentence(35, "Hydrate regularly with pure fresh water throughout the busy day.", "مصروف دن میں تازہ پانی کی مناسب مقدار پینا مت بھولیں۔", "Masroof din mein taaza paani peena mat bhoolin."),
                ConversionSentence(36, "Every difficult storm eventually runs out of rain; have faith.", "ہر اندھیری رات کے بعد اجالا ضرور ہوتا ہے؛ امید قائم رکھیں۔", "Har andheri raat ke baad ujala zaroor hota hai; umeed rakhein."),
                ConversionSentence(37, "Create a cozy, quiet reading corner in your bedroom for relaxation.", "گھر کے کسی کونے میں پرسکون مطالعے کی جگہ بنائیں۔", "Ghar ke kisi konay mein pursukoon mutala'a ki jagah banayein."),
                ConversionSentence(38, "Learn to say no politely to commitments that drain your energy.", "ان کاموں کو شائستگی سے نہ کہنا سیکھیں جو آپ کو تھکا دیتے ہیں۔", "Un kamon ko na kehna seekhein jo aap ko thaka detay hain."),
                ConversionSentence(39, "Spend time playing with pets or tending to flowering potted plants.", "پالتو جانوروں کے ساتھ وقت گزارنا یا پودے لگانا سکون دیتا ہے۔", "Paaltu janwaron ke sath waqt guzarna sukoon deta hai."),
                ConversionSentence(40, "Forgive yourself for past missteps; today is a brand-new page.", "ماضی کی غلطیوں پر خود کو معاف کریں؛ آج ایک نیا دن ہے۔", "Maazi ki ghaltiyon par khud ko maaf karein; aaj naya din hai."),
                ConversionSentence(41, "Mental clarity begins with accepting reality with patience and grace.", "ذہنی سکون حالات کو صبر اور وقار سے قبول کرنے سے شروع ہوتا ہے۔", "Zehni sukoon halaat ko sabr se qubool karne se shuru hota hai."),
                ConversionSentence(42, "Take brief five-minute sensory breaks: notice colors, sounds, and scents.", "دن میں چند منٹ اردگرد کے خوبصورت رنگوں اور خوشبوؤں کو محسوس کریں۔", "Din mein chand minute khubsurat rangon aur khushboo ko mehsoos karein."),
                ConversionSentence(43, "Listen with empathy when someone opens up about their struggles.", "جب کوئی اپنا دکھ بتائے تو پوری ہمدردی سے اس کی بات سنیں۔", "Jab koi dukh bataye to poori hamdardi se baat sunein."),
                ConversionSentence(44, "Your life has immense intrinsic worth and divine unique purpose.", "آپ کی زندگی انتہائی قیمتی اور ایک خاص مقصد کے تحت ہے۔", "Aap ki zindagi intehai qeemti aur ba-maqsad hai."),
                ConversionSentence(45, "Peace of heart is the ultimate luxury in a frantic modern world.", "اس تیز رفتار دنیا میں دل کا سکون سب سے بڑی نعمت ہے۔", "Is taiz dunya mein dil ka sukoon sab se barri nemat hai."),
                ConversionSentence(46, "Nourish your soul with uplifting spiritual books and poetry.", "روحانی اور فکری کتابوں سے اپنے دل کو تسکین دیں۔", "Roohani kitabon se apne dil ko taskeen dein."),
                ConversionSentence(47, "Remember that healing is a gradual journey, not a destination.", "یاد رکھیں کہ زخموں کا بھرنا ایک سفر ہے جس میں وقت لگتا ہے۔", "Yaad rakhein ke zakhmon ka bharna aik safar hai."),
                ConversionSentence(48, "You are never truly alone; help, hope, and compassion are near.", "آپ کبھی تنہا نہیں ہیں؛ مدد، امید اور رحمت ہمیشہ قریب ہے۔", "Aap kabhi tanha nahi hain; madad aur umeed qareeb hai."),
                ConversionSentence(49, "Treat yourself with immense patience as you journey toward healing and peace.", "صحت یابی اور سکون کے سفر میں اپنے ساتھ بے پناہ صبر اور محبت برتیں۔", "Sehat-yabi aur sukoon ke safar mein apne sath sabr bartein."),
                ConversionSentence(50, "May your heart find serene tranquility, inner resilience, and peace!", "اللہ تعالیٰ آپ کے دل کو دائمی قرار، سکون اور اطمینان بخشے!", "Allah Ta'ala aap ke dil ko daaimi qaraar aur sukoon bakhshay!")
            )),
            // 44. Time Management & Productivity (50 Sentences)
            ConversionTopic(44, "Time Management & Productivity", "وقت کی پابندی اور پیداواری صلاحیت", "schedule", "Prioritization, habits, focus blocks, deep work, and discipline.", listOf(
                ConversionSentence(1, "Time is our most non-renewable and precious earthly resource.", "وقت ہماری زندگی کا سب سے قیمتی اور نہ لوٹنے والا سرمایہ ہے۔", "Waqt hamari zindagi ka sab se qeemti sarmaya hai."),
                ConversionSentence(2, "Plan your daily schedule the previous evening before sleeping.", "اگلے دن کے کاموں کی فہرست سونے سے پہلے رات کو بنائیں۔", "Aglay din ke kamon ki fehrist sonay se pehle banayein."),
                ConversionSentence(3, "Use the Pomodoro technique: work twenty-five minutes, rest five.", "پومودورو طریقہ اپنائیں: پچیس منٹ کام کریں، پانچ منٹ آرام کریں۔", "Pomodoro tareeqa apnayein: 25 minute kaam, 5 minute aaram."),
                ConversionSentence(4, "Tackle your most demanding task first thing in the morning.", "سب سے مشکل اور اہم کام کو صبح سویرے سب سے پہلے نمٹائیں۔", "Sab se mushkil kaam subah sawairay sab se pehle karein."),
                ConversionSentence(5, "Eliminate distractions by putting smartphones on silent focus mode.", "یکسوئی کے لیے موبائل فون کو سائلنٹ موڈ پر رکھیں۔", "Yaksooi ke liye mobile phone ko silent mode par rakhein."),
                ConversionSentence(6, "Multi-tasking reduces cognitive efficiency and increases errors.", "ایک ساتھ کئی کام کرنا کارکردگی گھٹاتا ہے اور غلطیاں بڑھاتا ہے۔", "Aik sath kai kaam karna karkardagi kam karta hai."),
                ConversionSentence(7, "Batch similar errands together to save commute time and gas.", "ملتے جلتے کام ایک ساتھ کریں تاکہ وقت اور پٹرول دونوں بچیں۔", "Miltay jultay kaam aik sath karein taakay bachat ho."),
                ConversionSentence(8, "Set strict, clear timeboxes for checking emails and messages.", "ای میلز اور پیغامات دیکھنے کے لیے مخصوص اوقات مقرر کریں۔", "Emails aur messages ke liye makhsoos auqaat muqarrar karein."),
                ConversionSentence(9, "Learn to politely decline requests that do not align with goals.", "اپنے مقاصد سے ہٹانے والے کاموں کو شائستگی سے انکار کریں۔", "Apne maqasid se hatanay walay kamon se inkaar karein."),
                ConversionSentence(10, "Consistency and daily compounding effort produce massive results.", "روزانہ کی مستقل محنت وقت کے ساتھ شاندار نتائج دیتی ہے۔", "Rozana ki mustaqil mehnat waqt ke sath nataij deti hai."),
                ConversionSentence(11, "How do you overcome chronic procrastination on daunting tasks?", "آپ کام کو ٹالنے کی عادت پر کیسے قابو پاتے ہیں؟", "Aap kaam ko taalnay ki aadat par kaisay qaabu paatay hain?"),
                ConversionSentence(12, "Use the 2-minute rule: if it takes under two minutes, do it now.", "اگر کوئی کام دو منٹ سے کم وقت لیتا ہے تو اسے فوری نمٹا دیں۔", "Agar kaam 2 minute se kam le to fauri nibta dein."),
                ConversionSentence(13, "Organize your digital files into clear, intuitive nested folders.", "کمپیوٹر کی فائلز کو سلیقے سے الگ الگ فولڈرز میں رکھیں۔", "Computer files ko saleeqay se folders mein rakhein."),
                ConversionSentence(14, "Keep your physical work area uncluttered for crystal clarity.", "ذہنی یکسوئی کے لیے اپنی میز کو ہمیشہ صاف ستھرا رکھیں۔", "Zehni yaksooi ke liye apni maiz saaf rakhein."),
                ConversionSentence(15, "Review your weekly accomplishments every Sunday afternoon.", "ہر اتوار کی دوپہر پورے ہفتے کی کارکردگی کا جائزہ لیں۔", "Har itwar pooray haftay ki karkardagi ka jaiza lein."),
                ConversionSentence(16, "Distinguish clearly between busy activity and genuine productivity.", "محض مصروف رہنے اور حقیقی کام کرنے کے فرق کو سمجھیں۔", "Sirf masroof rehnay aur haqeeqi kaam ka farq samjhein."),
                ConversionSentence(17, "Automate repetitive digital tasks using keyboard shortcuts and scripts.", "بار بار ہونے والے کاموں کو شارٹ کٹس کے ذریعے تیز بنائیں۔", "Baar baar honay walay kamon ko shortcuts se taiz karein."),
                ConversionSentence(18, "Protect your peak cognitive hours for deep creative work.", "صبح کے پرسکون گھنٹوں کو اہم تخلیقی کاموں کے لیے مخصوص کریں۔", "Subah ke pursukoon ghanton ko ahem kamon ke liye rakhein."),
                ConversionSentence(19, "Take real screen-free breaks to replenish your mental energy.", "تھکن دور کرنے کے لیے اسکرین سے دور رہ کر وقفہ لیں۔", "Thakan door karne ke liye screen se door waqfa lein."),
                ConversionSentence(20, "A disciplined morning routine sets the tone for an effective day.", "صبح کا باقاعدہ معمول پورے دن کو کامیاب اور بااثر بناتا ہے۔", "Subah ka mamool pooray din ko kamyab banata hai."),
                ConversionSentence(21, "Use visual task tracking tools like Kanban boards to see progress.", "کام کی پیش رفت دیکھنے کے لیے کانبان بورڈز کا استعمال کریں۔", "Kaam ki paish-raft dekhnay ke liye Kanban boards istemal karein."),
                ConversionSentence(22, "Set realistic deadlines with a twenty percent buffer margin.", "ڈیڈ لائنز طے کرتے وقت بیس فیصد اضافی وقت ساتھ رکھیں۔", "Deadlines tay kartay waqt izafi waqt sath rakhein."),
                ConversionSentence(23, "Do not let perfectionism paralyze you from completing tasks.", "بہترین کے چکر میں کام کو ادھورا مت چھوڑیں، کام مکمل کریں۔", "Behtareen ke chakkar mein kaam ko adhoora mat chhorrein."),
                ConversionSentence(24, "Done is far better than perfect but perpetually unfinished.", "مکمل ہو جانا اس سے بہتر ہے کہ چیز ہمیشہ نامکمل پڑی رہے۔", "Mukammal ho jana na-mukammal rehnay se behtar hai."),
                ConversionSentence(25, "Track how you spend your waking hours for three full days.", "تین دن کے لیے نوٹ کریں کہ آپ کا وقت کہاں خرچ ہوتا ہے۔", "Teen din ke liye note karein waqt kahan kharch hota hai."),
                ConversionSentence(26, "Eliminate low-value habits that consume hours of daily focus.", "ان فضول عادتوں کو چھوڑیں جو روزانہ گھنٹوں ضائع کرتی ہیں۔", "Un fazool aadaton ko chhorrein jo waqt zaya karti hain."),
                ConversionSentence(27, "Create standard operating checklists for recurring processes.", "روزمرہ کے معمولات کے لیے چیک لسٹ کا استعمال کریں۔", "Rozmarrah ke mamoolat ke liye checklist istemal karein."),
                ConversionSentence(28, "Delegate routine administrative tasks whenever feasible.", "چھوٹے دفتری کام ٹیم کے دیگر ارکان میں تقسیم کریں۔", "Chhotay daftari kaam team mein taqseem karein."),
                ConversionSentence(29, "Single-task with full presence and immerse yourself completely.", "ایک وقت میں ایک ہی کام پر پوری توجہ کے ساتھ لگ جائیں۔", "Aik waqt mein aik hi kaam par poori tawajjo dein."),
                ConversionSentence(30, "Time well-invested today buys freedom and peace tomorrow.", "آج سنبھالا گیا وقت کل کی آزادی اور سکون خریدتا ہے۔", "Aaj sambhala gaya waqt kal ki azaadi aur sukoon deta hai."),
                ConversionSentence(31, "Avoid checking social media notifications during focus blocks.", "کام کے دوران سوشل میڈیا کے نوٹیفیکیشنز مت دیکھیں۔", "Kaam ke dauran social media notifications mat dekhein."),
                ConversionSentence(32, "Set a timer for sixty minutes and work with zero interruptions.", "ساٹھ منٹ کا ٹائمر لگائیں اور بغیر کسی مداخلت کے کام کریں۔", "60 minute ka timer lagayein aur tawajjo se kaam karein."),
                ConversionSentence(33, "Keep a notepad handy to jot down sudden distracting thoughts.", "دھیان بھٹکانے والے خیالات فوراً نوٹ پیڈ پر لکھ لیں۔", "Dhyan bhatkanay walay khayalaat notepad par likh lein."),
                ConversionSentence(34, "Address those thoughts only after completing your active task.", "اپنا کام مکمل کرنے کے بعد ہی ان باتوں کو دیکھیں۔", "Apna kaam mukammal karne ke baad hi unhein dekhein."),
                ConversionSentence(35, "Reward yourself with a refreshing treat after major tasks.", "مشکل کام پورا ہونے پر خود کو کوئی چھوٹا سا انعام دیں۔", "Mushkil kaam poora honay par khud ko inaam dein."),
                ConversionSentence(36, "Energy management is just as crucial as time management.", "وقت کی طرح جسمانی توانائی کا انتظام بھی بے حد ضروری ہے۔", "Waqt ki tarah jismani tawanaai ka intezam zaroori hai."),
                ConversionSentence(37, "Stay physically active to maintain high stamina throughout the day.", "سارا دن چست رہنے کے لیے ہلکی پھلکی ورزش جاری رکھیں۔", "Sara din chust rehnay ke liye warzish jaari rakhein."),
                ConversionSentence(38, "Schedule downtime and family leisure with the same seriousness.", "خاندان اور تفریح کا وقت بھی اتنی ہی سنجیدگی سے طے کریں۔", "Khandan aur tafreeh ka waqt bhi sanjeedgi se tay karein."),
                ConversionSentence(39, "A well-rested mind generates creative breakthroughs effortlessly.", "تازہ دم ذہن آسانی سے نئے اور شاندار حل تلاش کرتا ہے۔", "Taaza dam zehan aasani se naye hal talash karta hai."),
                ConversionSentence(40, "Focus on the vital few high-impact 20% tasks that drive 80% results.", "ان بیس فیصد اہم کاموں پر توجہ دیں جو اسی فیصد نتائج دیتے ہیں۔", "Un 20% ahem kamon par dhyan dein jo 80% nataij detay hain."),
                ConversionSentence(41, "Organize your email inbox with folders and clear zero inbox.", "اپنے ای میل ان باکس کو سلیقے سے صاف رکھیں۔", "Apne email inbox ko saleeqay se saaf rakhein."),
                ConversionSentence(42, "Prepare your clothes and work bag the night before.", "اگلے دن کے کپڑے اور بیگ رات کو ہی تیار رکھیں۔", "Aglay din ke kapray aur bag raat ko hi tayar rakhein."),
                ConversionSentence(43, "Punctuality honors other people's time and builds immense trust.", "وقت کی پابندی دوسروں کا احترام اور اعتماد قائم کرتی ہے۔", "Waqt ki pabandi doosron ka ihtiram aur aitemad banati hai."),
                ConversionSentence(44, "Never make excuses for missed deadlines; own up and deliver.", "ڈیڈ لائن نکلنے پر بہانے نہ بنائیں بلکہ کام مکمل کر کے دیں۔", "Deadline nikalnay par bahaane na banayein, kaam karein."),
                ConversionSentence(45, "High performers protect their focus ruthlessly from distractions.", "کامیاب لوگ اپنی توجہ کو ہر قسم کے بگاڑ سے بچاتے ہیں۔", "Kamyab log apni tawajjo ko bachatay hain."),
                ConversionSentence(46, "Master the habit of deep work in an age of constant distraction.", "ہر طرف پھیلے شور میں یکسوئی سے کام کرنے کی عادت ڈالیں۔", "Har taraf phailay shor mein yaksooi se kaam seekhein."),
                ConversionSentence(47, "Small daily improvements compound into staggering achievements.", "روزانہ کی چھوٹی بہتری وقت کے ساتھ بڑی کامیابی بن جاتی ہے۔", "Rozana ki chhoti behtari barri kamyabi banti hai."),
                ConversionSentence(48, "Cherish every ticking second as a golden gift from above.", "گزرتے ہوئے ہر سیکنڈ کو قدرت کا انمول تحفہ جانیں۔", "Guzartay hue har second ko qudrat ka anmol tohfa jaanein."),
                ConversionSentence(49, "Thank you for choosing discipline, focus, and dedicated effort.", "نظم و ضبط، یکسوئی اور محنت کا راستہ چننے پر آپ کو سلام۔", "Nazm-o-zabt aur mehnat ka rasta chun-nay par salam."),
                ConversionSentence(50, "May your daily hours be crowned with barakah and immense triumph!", "اللہ تعالیٰ آپ کے وقت میں بے پناہ برکت اور کامیابی عطا فرمائے!", "Allah Ta'ala aap ke waqt mein barkat aur kamyabi ata farmaye!")
            )),
            // 45. Traveling Abroad & Visas (50 Sentences)
            ConversionTopic(45, "Traveling Abroad & Visas", "بیرون ملک سفر اور ویزا", "flight_takeoff", "Visas, embassies, airports, flights, customs, and travel tips.", listOf(
                ConversionSentence(1, "I need to apply for a tourist visit visa at the embassy.", "مجھے سفارت خانے سے سیاحتی ویزا کے لیے درخواست دینی ہے۔", "Mujhe safarat-khanay se visit visa ke liye apply karna hai."),
                ConversionSentence(2, "Ensure your passport has at least six months of remaining validity.", "دیکھ لیں کہ پاسپورٹ کی میعاد میں کم از کم چھ ماہ باقی ہوں۔", "Dekh lein ke passport ki meyaad mein 6 maah baaqi hon."),
                ConversionSentence(3, "What supporting financial documents are required for the visa interview?", "ویزا انٹرویو کے لیے کون سے مالی کاغذات ساتھ لے جانے ہیں؟", "Visa interview ke liye kaun se maali kaghazat chahiyein?"),
                ConversionSentence(4, "You need six months of certified bank statements and tax returns.", "چھ ماہ کا تصدیق شدہ بینک اسٹیٹمنٹ اور ٹیکس ریٹرنز درکار ہیں۔", "6 maah ka bank statement aur tax returns darkaar hain."),
                ConversionSentence(5, "We booked return flight tickets with a reputable international airline.", "ہم نے ایک معتبر ایئرلائن کی دو طرفہ ٹکٹیں بک کروائیں۔", "Hum ne aik achi airline ki return tickets book karwayein."),
                ConversionSentence(6, "What is the maximum baggage weight allowance per passenger?", "فی مسافر سامان کا زیادہ سے زیادہ کتنا وزن لے جانے کی اجازت ہے؟", "Fi musafir saman ka zyada se zyada kitna wazan allowed hai?"),
                ConversionSentence(7, "Carry all original educational degrees, certificates, and ID cards.", "اپنی تمام اصل تعلیمی اسناد، سرٹیفکیٹس اور شناختی کارڈ ساتھ رکھیں۔", "Apni tamam asal asnaad aur card sath rakhein."),
                ConversionSentence(8, "Ensure you purchase comprehensive international travel health insurance.", "بین الاقوامی سفر کے لیے ہیلتھ انشورنس ضرور خریدیں۔", "International safar ke liye travel health insurance zaroor lein."),
                ConversionSentence(9, "The immigration officer stamped my passport with a multiple-entry visa.", "امیگریشن افسر نے میرے پاسپورٹ پر ملٹیپل انٹری ویزا لگا دیا۔", "Immigration officer ne passport par visa laga diya."),
                ConversionSentence(10, "Travel opens your eyes to diverse human cultures and global wonders.", "سفر انسان کی آنکھیں کھولتا ہے اور دنیا کی وسعتیں دکھاتا ہے۔", "Safar insaan ki aankhein kholta hai aur dunya dikhata hai."),
                ConversionSentence(11, "How long is the layover transit time between connecting flights?", "کنیکٹنگ فلائٹس کے درمیان ایئرپورٹ پر رکنے کا کتنا وقت ہے؟", "Connecting flights ke darmiyan kitna transit time hai?"),
                ConversionSentence(12, "We must clear airport security and border control two hours early.", "ہمیں سیکیورٹی اور امیگریشن کے لیے دو گھنٹے پہلے پہنچنا ہوگا۔", "Humein security aur immigration ke liye 2 ghantay pehle jana hoga."),
                ConversionSentence(13, "Declare any foreign currency exceeding ten thousand dollars at customs.", "دس ہزار ڈالر سے زائد غیر ملکی رقم کسٹمز پر ڈیکلیئر کریں۔", "10 hazar dollar se zyada raqam customs par declare karein."),
                ConversionSentence(14, "Keep your passport, boarding passes, and wallet in a secure pouch.", "پاسپورٹ، بورڈنگ پاس اور رقم ہمیشہ محفوظ بیگ میں رکھیں۔", "Passport, boarding pass aur raqam mahfooz bag mein rakhein."),
                ConversionSentence(15, "Pack essential daily medications in your cabin carry-on luggage.", "اپنی ضروری روزمرہ ادویات ہاتھ والے کیبن بیگ میں رکھیں۔", "Zaroori adwiyaat hath walay cabin bag mein rakhein."),
                ConversionSentence(16, "Download offline digital maps of the destination city on your phone.", "منزل والے شہر کے آف لائن نقشے اپنے موبائل میں ڈاؤن لوڈ کریں۔", "Manzil walay shehar ke offline maps mobile mein save karein."),
                ConversionSentence(17, "Exchange currency at official bank counters to get fair rates.", "کرنسی کا تبادلہ ہمیشہ بینک کے مستند کاؤنٹر سے کروائیں۔", "Currency ka tabadla hamesha bank ke counter se karwayein."),
                ConversionSentence(18, "Respect the cultural norms, customs, and laws of foreign lands.", "غیر ممالک کے قوانین، آداب اور روایات کا ہمیشہ احترام کریں۔", "Ghair mumalik ke qawaneen aur aadab ka ihtiram karein."),
                ConversionSentence(19, "Our flight landed smoothly on the runway despite windy weather.", "تیز ہواؤں کے باوجود ہماری پرواز بحفاظت رن وے پر اتر گئی۔", "Hawaon ke bawajood flight ba-hifazat runway par utar gayi."),
                ConversionSentence(20, "Traveling as a guest builds mutual goodwill and global friendship.", "ایک اچھے سیاح کی طرح سفر کرنا قوموں میں دوستی بڑھاتا ہے۔", "Achay sayyah ki tarah safar dosti barhata hai."),
                ConversionSentence(21, "Do you need a transit visa for a twelve-hour airport connection?", "کیا بارہ گھنٹے کے قیام کے لیے ٹرانزٹ ویزا درکار ہے؟", "Kya 12 ghantay ke stay ke liye transit visa chahiye?"),
                ConversionSentence(22, "Check the customs duty restrictions on imported electronics.", "باہر سے لائے جانے والے الیکٹرانکس پر کسٹمز ڈیوٹی چیک کریں۔", "Electronics par customs duty ke qawaneen check karein."),
                ConversionSentence(23, "Fasten your seatbelt securely whenever the seatbelt sign is illuminated.", "سیٹ بیلٹ کا نشان جلتے ہی اپنی بیلٹ فوری باندھ لیں۔", "Seatbelt ka nishan jaltay hi belt baandh lein."),
                ConversionSentence(24, "The flight attendant served hot halal meals during the long journey.", "فلائٹ اٹینڈنٹ نے طویل سفر کے دوران گرم حلال کھانا پیش کیا۔", "Flight attendant ne safar mein garam halaal khana diya."),
                ConversionSentence(25, "Keep a digital photograph of your passport and visa on email.", "پاسپورٹ اور ویزا کی کاپی اپنی ای میل پر ہمیشہ محفوظ رکھیں۔", "Passport aur visa ki copy email par mahfooz rakhein."),
                ConversionSentence(26, "What is the local emergency ambulance and police number here?", "یہاں مقامی ایمبولینس اور پولیس کا ایمرجنسی نمبر کیا ہے؟", "Yahan emergency ambulance aur police ka number kya hai?"),
                ConversionSentence(27, "Purchase a local prepaid data SIM card at the airport arrival hall.", "ایئرپورٹ پہنچتے ہی انٹرنیٹ ڈیٹا والی لوکل سم خرید لیں۔", "Airport pohanchtay hi local internet SIM khareed lein."),
                ConversionSentence(28, "Learn a few basic phrases in the local language of the host nation.", "میزبان ملک کی زبان کے چند بنیادی الفاظ اور جملے سیکھیں۔", "Mezban mulk ki zaban ke ahem alfaaz seekhein."),
                ConversionSentence(29, "Always keep your hotel business card with address in your pocket.", "ہوٹل کا کارڈ پتہ کے ساتھ ہمیشہ اپنی جیب میں رکھیں۔", "Hotel ka card address ke sath hamesha paas rakhein."),
                ConversionSentence(30, "A pleasant smile bridges linguistic divides in any foreign city.", "ایک خوبصورت مسکراہٹ کسی بھی غیر ملک میں زبان کی دوری مٹا دیتی ہے۔", "Aik muskurahat kisi bhi mulk mein zaban ki doori mita deti hai."),
                ConversionSentence(31, "Are luggage carts available free of charge in the baggage claim?", "کیا سامان اٹھانے والی ٹرالیاں ایئرپورٹ پر مفت دستیاب ہیں؟", "Kya saman ki trolleys airport par muft hain?"),
                ConversionSentence(32, "Collect your checked baggage from carousel number four.", "بیلٹ نمبر چار سے اپنا بک کروایا گیا سامان وصول کریں۔", "Belt number 4 se apna saman wasool karein."),
                ConversionSentence(33, "If your baggage is delayed, report to the lost luggage counter.", "اگر سامان نہ پہنچے تو گمشدہ سامان کے کاؤنٹر پر رپورٹ کریں۔", "Agar saman na pohanchay to lost luggage par report karein."),
                ConversionSentence(34, "Confirm your departure terminal and boarding gate in advance.", "اپنا ٹرمینل اور بورڈنگ گیٹ پہلے سے کنفرم کر لیں۔", "Apna terminal aur boarding gate pehle se confirm karein."),
                ConversionSentence(35, "Drink plenty of water on long flights to avoid jet lag fatigue.", "طویل پروازوں کے دوران تھکن سے بچنے کے لیے زیادہ پانی پئیں۔", "Lambi flights mein thakan se bachnay ke liye paani piyein."),
                ConversionSentence(36, "Set your watch to the destination time zone upon boarding.", "جہاز میں بیٹھتے ہی اپنی گھڑی کا وقت منزل کے مطابق کر لیں۔", "Jahaz mein baithtay hi ghari ka waqt manzil ke mutabiq karein."),
                ConversionSentence(37, "Keep your passport handy when boarding the aircraft.", "جہاز میں سوار ہوتے وقت اپنا پاسپورٹ ہاتھ میں رکھیں۔", "Jahaz mein sawaar hotay waqt passport hath mein rakhein."),
                ConversionSentence(38, "Do not leave your personal bags unattended at the airport.", "ایئرپورٹ پر اپنا سامان کبھی لاوارث مت چھوڑیں۔", "Airport par apna saman kabhi la-waaris mat chhorrein."),
                ConversionSentence(39, "Follow all airport signage carefully to find your connecting gate.", "اگلے گیٹ تک پہنچنے کے لیے سائن بورڈز پر نظر رکھیں۔", "Aglay gate tak pohanchnay ke liye signboards dekhein."),
                ConversionSentence(40, "Traveling enriches the mind with wisdom and humility.", "سفر انسان کے ذہن کو حکمت، علم اور عاجزی عطا کرتا ہے۔", "Safar insaan ke zehan ko hikmat aur ilm deta hai."),
                ConversionSentence(41, "Ensure your international credit card is enabled for foreign spend.", "دیکھ لیں کہ کارڈ بیرون ملک ادائیگیوں کے لیے کھلا ہو۔", "Dekh lein ke card bairoon-e-mulk payments ke liye khula ho."),
                ConversionSentence(42, "Dress comfortably in loose layers for long overnight international flights.", "لمبی پروازوں کے لیے آرام دہ اور ڈھیلا لباس پہنیں۔", "Lambi flights ke liye aaram deh libaas pehnein."),
                ConversionSentence(43, "Check the weather forecast of your destination before packing.", "سامان پیک کرنے سے پہلے منزل کے موسم کی صورتحال دیکھیں۔", "Saman pack karne se pehle manzil ka mausam dekhein."),
                ConversionSentence(44, "Keep a pen in your bag to fill out customs declaration cards.", "کسٹمز فارم بھرنے کے لیے اپنے بیگ میں پین ساتھ رکھیں۔", "Customs form bharnay ke liye bag mein pen sath rakhein."),
                ConversionSentence(45, "Store your passport in the hotel safety deposit locker.", "ہوٹل کے کمرے میں پاسپورٹ محفوظ لاکر میں رکھیں۔", "Hotel ke kamray mein passport safe locker mein rakhein."),
                ConversionSentence(46, "Be polite and respectful to airline staff and border officers.", "ایئرپورٹ عملے اور بارڈر افسران سے ہمیشہ ادب سے پیش آئیں۔", "Airport amlay aur officers se hamesha adab se pesh aayein."),
                ConversionSentence(47, "Capture beautiful memories and write down travel reflections.", "خوبصورت تصاویر لیں اور اپنے سفری تجربات کو ڈائری میں لکھیں۔", "Khubsurat photos lein aur safar ki yaadein likhein."),
                ConversionSentence(48, "Safe travels and smooth journeys across skies and lands!", "اللہ تعالیٰ آپ کے تمام اسفار کو محفوظ اور آسان فرمائے!", "Allah Ta'ala aap ke safar ko mahfooz aur aasan farmaye!"),
                ConversionSentence(49, "Every new destination teaches us deep appreciation for our own homeland.", "ہر نیا ملک ہمیں اپنے وطن کی قدر و قیمت کا مزید احساس دلاتا ہے۔", "Har naya mulk humein apne watan ki qadr ka ehsas dilata hai."),
                ConversionSentence(50, "May your international voyage be rewarding and transformative!", "اللہ کرے آپ کا بیرون ملک سفر کامیابیوں اور علم سے بھرپور ہو!", "Allah karay aap ka safar kamyabi aur ilm se bharpoor ho!")
            )),
            // 46. Driving & Road Safety (50 Sentences)
            ConversionTopic(46, "Driving & Road Safety", "ڈرائیونگ اور ٹریفک قوانین", "directions_car", "Signals, speed limits, parking, vehicle maintenance, and highway safety.", listOf(
                ConversionSentence(1, "Always fasten your three-point seatbelt before turning on the engine.", "گاڑی اسٹارٹ کرنے سے پہلے سیٹ بیلٹ باندھنا لازمی عادت بنائیں۔", "Gaari start karne se pehle seatbelt baandhein."),
                ConversionSentence(2, "Never use your mobile phone while driving on busy highways.", "مصروف سڑکوں پر گاڑی چلاتے وقت موبائل فون کا استعمال ہرگز نہ کریں۔", "Sarakon par gaari chalatay waqt mobile istemal na karein."),
                ConversionSentence(3, "Obey traffic signals, speed limits, and pedestrian zebra crossings.", "ٹریفک سگنلز، رفتار کی حد اور زیبرا کراسنگ کا مکمل احترام کریں۔", "Traffic signals aur speed limits ka ihtiram karein."),
                ConversionSentence(4, "Check your rear-view and side mirrors before changing lanes.", "لین تبدیل کرنے سے پہلے دائیں بائیں اور بیک ویو شیشے ضرور دیکھیں۔", "Lane badalnay se pehle side mirrors zaroor dekhein."),
                ConversionSentence(5, "Use your turn indicators well in advance when making a turn.", "موڑ مڑنے سے کافی پہلے انڈیکیٹر کا اشارہ دیں۔", "Morr murnay se pehle indicator ka ishara dein."),
                ConversionSentence(6, "Maintain a safe three-second braking distance from the car ahead.", "سامنے والی گاڑی سے کم از کم تین سیکنڈ کے فاصلے پر رہیں۔", "Samnay wali gaari se faasla barqarar rakhein."),
                ConversionSentence(7, "Check your vehicle's engine oil level and tire pressure weekly.", "ہر ہفتے گاڑی کا انجن آئل اور ٹائروں میں ہوا کا پریشر چیک کریں۔", "Har haftay engine oil aur tire pressure check karein."),
                ConversionSentence(8, "Slow down and drive cautiously in heavy rain and slippery mud.", "تیز بارش اور پھسلن والی سڑک پر گاڑی کی رفتار کم رکھیں۔", "Taiz barish mein gaari ki raftaar kam rakhein."),
                ConversionSentence(9, "Turn on your fog lights and hazard lights during dense winter fog.", "سردیوں کی شدید دھند میں فوگ لائٹس ضرور آن کریں۔", "Sardiyon ki dhund mein fog lights on karein."),
                ConversionSentence(10, "Road safety saves precious human lives and prevents tragedies.", "ٹریفک قوانین کی پابندی قیمتی انسانی جانوں کی حفاظت کرتی ہے۔", "Traffic qawaneen ki pabandi insani janon ki hifazat karti hai."),
                ConversionSentence(11, "How do I parallel park smoothly in a tight crowded parking spot?", "تنگ جگہ پر گاڑی کو سلیقے سے متوازی کیسے پارک کیا جائے؟", "Tang jagah par gaari parallel park kaisay karein?"),
                ConversionSentence(12, "Always give way to emergency ambulances and fire brigade trucks.", "ایمبولینس اور فائر بریگیڈ کی گاڑیوں کو ہمیشہ راستہ دیں۔", "Ambulance aur fire brigade ko hamesha rasta dein."),
                ConversionSentence(13, "Do not overtake recklessly from the wrong left side on highways.", "موٹروے پر بائیں جانب سے خطرناک اوور ٹیکنگ سے پرہیز کریں۔", "Motorway par ghalt side se overtake na karein."),
                ConversionSentence(14, "Carry your driving license, vehicle registration, and insurance tokens.", "اپنا ڈرائیونگ لائسنس اور گاڑی کے کاغذات ہمیشہ ساتھ رکھیں۔", "Apna driving license aur kaghazat sath rakhein."),
                ConversionSentence(15, "Ensure your headlights are aligned properly and not blinding drivers.", "دیکھیں کہ ہیڈلائٹس سامنے والوں کی آنکھوں میں نہ لگ رہی ہوں۔", "Dekhein ke headlights samnay walon ko tang na karein."),
                ConversionSentence(16, "Replace worn-out windshield wiper blades before rainy monsoon.", "برسات سے پہلے ونڈ اسکرین کے پرانے وائپرز تبدیل کروائیں۔", "Barsaat se pehle wipers tabdeel karwayein."),
                ConversionSentence(17, "Never drive when fatigued; pull over at a rest stop for coffee.", "نیند اور تھکن میں ڈرائیونگ نہ کریں؛ سروس ایریا پر رکیں۔", "Neend aur thakan mein driving na karein; aaram karein."),
                ConversionSentence(18, "Pedestrians and cyclists have the right of way in residential zones.", "رہائشی علاقوں میں پیدل چلنے والوں کو ہمیشہ پہلے راستہ دیں۔", "Rehaishi ilaaqon mein paidal chalnay walon ko rasta dein."),
                ConversionSentence(19, "Avoid aggressive road rage; patience defuses volatile traffic tension.", "غصے اور تکرار سے بچیں؛ صبر ٹریفک کا غصہ ختم کرتا ہے۔", "Ghussay se bachein; sabr traffic mein laraai rokata hai."),
                ConversionSentence(20, "A safe, courteous driver protects everyone sharing the open road.", "ایک شائستہ ڈرائیور سڑک پر موجود ہر شخص کا محافظ ہوتا ہے۔", "Aik shaista driver har shakhs ka muhafiz hota hai."),
                ConversionSentence(21, "Inspect your vehicle's spare tire, jack, and wheel spanner.", "گاڑی کا اضافی ٹائر (اسٹپنی) اور جیک باقاعدگی سے چیک کریں۔", "Gaari ka stepney tire aur jack check karein."),
                ConversionSentence(22, "Never leave young children or pets unattended inside parked cars.", "پارک کی گئی گاڑی میں بچوں کو کبھی تنہا مت چھوڑیں۔", "Gaari mein bachon ko kabhi tanha mat chhorrein."),
                ConversionSentence(23, "Adhere to school zone speed limits of twenty kilometers per hour.", "اسکولوں کے قریب رفتار بیس کلومیٹر فی گھنٹہ سے زیادہ نہ رکھیں۔", "School ke qareeb raftaar 20 km/h se zyada na rakhein."),
                ConversionSentence(24, "Check your brake fluid and radiator coolant levels regularly.", "بریک آئل اور ریڈی ایٹر کا کولنٹ باقاعدگی سے چیک کریں۔", "Brake oil aur coolant baqaidgi se check karein."),
                ConversionSentence(25, "Never drive under the influence of medications causing drowsiness.", "غنودگی لانے والی ادویات کھا کر گاڑی ہرگز نہ چلائیں۔", "Ghanoodgi wali medicines khaa kar driving na karein."),
                ConversionSentence(26, "Always stop completely behind the white line at red traffic lights.", "سرخ اشارے پر سفید لکیر کے پیچھے مکمل گاڑی روکیں۔", "Laal batii par safaid line ke peechay gaari rokein."),
                ConversionSentence(27, "Motorcyclists must always wear a certified protective helmet.", "موٹر سائیکل سوار ہمیشہ معیاری ہیلمٹ پہنیں۔", "Motorcycle sawaar hamesha helmet pehnein."),
                ConversionSentence(28, "Use low beam headlights when driving through heavy urban traffic.", "شہر کے اندر ہمیشہ لو بیم لائٹس استعمال کریں۔", "Shehar ke andar low beam lights istemal karein."),
                ConversionSentence(29, "Keep a small fire extinguisher and first aid kit in the car trunk.", "گاڑی کی ڈگی میں فرسٹ ایڈ کٹ اور آگ بجھانے والا آلہ رکھیں۔", "Gaari ki diggi mein first aid kit aur safety aalaat rakhein."),
                ConversionSentence(30, "Safe driving is a mark of high civic responsibility and character.", "محفوظ ڈرائیونگ اچھے شہری اور بلند اخلاق کی پہچان ہے۔", "Mahfooz driving achay shehri ki pehchan hai."),
                ConversionSentence(31, "What should you do if your car engine overheats on motorway?", "اگر موٹروے پر گاڑی کا انجن گرم ہو جائے تو کیا کرنا چاہیے؟", "Agar motorway par gaari garam ho jaye to kya karein?"),
                ConversionSentence(32, "Safely guide your vehicle to the emergency hard shoulder lane.", "گاڑی کو آرام سے سائیڈ پر ایمرجنسی لین میں کھڑا کریں۔", "Gaari ko side par emergency lane mein kharra karein."),
                ConversionSentence(33, "Turn on your emergency hazard blinkers and set up warning triangles.", "ایمرجینسی لائٹس آن کریں اور دور تک تنبیہی اشارہ لگائیں۔", "Emergency lights on karein aur triangle lagayein."),
                ConversionSentence(34, "Wait for highway motorway police helpline 130 to arrive safely.", "موٹروے پولیس کی ہیلپ لائن ایک سو تیس پر کال کر کے انتظار کریں۔", "Motorway police helpline 130 par call karein."),
                ConversionSentence(35, "Ensure your child rides in an age-appropriate rear car seat.", "چھوٹے بچوں کے لیے کار سیٹ کا استعمال لازمی بنائیں۔", "Chhotay bachon ke liye car seat istemal karein."),
                ConversionSentence(36, "Avoid sudden harsh acceleration and aggressive braking to save fuel.", "اچانک ریس دینے اور بریک لگانے سے پرہیز کریں تاکہ پٹرول بچے۔", "Achanak race aur brake se parhez karein taakay petrol bachay."),
                ConversionSentence(37, "Rotate your tires every ten thousand kilometers for even wear.", "ٹائروں کی عمر بڑھانے کے لیے ہر دس ہزار کلومیٹر پر پوزیشن بدلیں۔", "Tires ki position har 10 hazar km par badlein."),
                ConversionSentence(38, "Keep your windows rolled up during severe sandstorms or smog.", "گرد کے طوفان یا اسموگ میں شیشے مکمل بند رکھیں۔", "Toofan ya smog mein sheeshay band rakhein."),
                ConversionSentence(39, "Pay attention to flashing yellow caution lights at intersections.", "چوراہے پر جلتی بجھتی پیلی بتی پر محتاط ہو کر نکلیں۔", "Chaurahay par peeli batti par ahtiyat karein."),
                ConversionSentence(40, "Patience and humility behind the wheel prevent road accidents.", "اسٹیئرنگ وہیل کے پیچھے صبر اور عاجزی حادثات سے بچاتی ہے۔", "Steering wheel ke peechay sabr haadsaat se bachata hai."),
                ConversionSentence(41, "Always lock car doors and do not leave valuables visible on seats.", "گاڑی کے دروازے لاک کریں اور سامان سیٹ پر مت چھوڑیں۔", "Darwazay lock karein aur saman seat par na chhorrein."),
                ConversionSentence(42, "Check that all brake lights and reverse lights are functioning.", "تسلی کریں کہ تمام پچھلی بریک لائٹس صحیح جل رہی ہوں۔", "Dekhein ke pichli brake lights sahi kaam kar rahi hon."),
                ConversionSentence(43, "Allow cyclists plenty of room when passing them on narrow roads.", "تنگ سڑکوں پر سائیکل سواروں کو مناسب فاصلہ دیں۔", "Tang sarakon par cycle walon ko faasla dein."),
                ConversionSentence(44, "Drive at a calm, steady pace that keeps passengers comfortable.", "گاڑی کو پرسکون اور متوازن رفتار میں چلائیں۔", "Gaari ko pursukoon raftaar mein chalayein."),
                ConversionSentence(45, "Respect the instructions of traffic wardens managing busy junctions.", "ٹریفک وارڈنز کے اشاروں اور ہدایات پر عمل کریں۔", "Traffic wardens ki hidayaat par amal karein."),
                ConversionSentence(46, "Keep your windshield clean and topped with washer fluid.", "ونڈ اسکرین کو ہمیشہ صاف اور پانی سے بھرا رکھیں۔", "Windscreen ko hamesha saaf rakhein."),
                ConversionSentence(47, "Never rush recklessly; reaching safely is the true priority.", "کبھی جلد بازی مت کریں؛ بحفاظت پہنچنا اصل مقصد ہے۔", "Kabhi jald-baazi mat karein; hifazat awaleen hai."),
                ConversionSentence(48, "Courteous drivers create a polite, peaceful civilized society.", "شائستہ ڈرائیور ایک مہذب اور پرامن معاشرہ بناتے ہیں۔", "Shaista drivers aik mohazzab ma'ashra banatay hain."),
                ConversionSentence(49, "Wishing you safe, peaceful, and pleasant journeys on every road!", "اللہ تعالیٰ آپ کے ہر سفر کو محفوظ، پرامن اور آسان بنائے!", "Allah Ta'ala aap ke har safar ko mahfooz banaye!"),
                ConversionSentence(50, "May you always reach your destinations in safety, peace, and health!", "اللہ کرے آپ ہمیشہ اپنی منزلوں پر خیر و عافیت سے پہنچیں!", "Allah karay aap hamesha khairiyat se pohanchein!")
            )),
            // 47. Job Interviews & Career Growth (50 Sentences)
            ConversionTopic(47, "Job Interviews & Career Growth", "ملازمت کے انٹرویوز اور ترقی", "work", "Strengths, salary negotiation, leadership, career paths, and poise.", listOf(
                ConversionSentence(1, "Tell me about yourself, your educational background, and experience.", "اپنے بارے میں، اپنی تعلیم اور کام کے تجربے سے آگاہ کریں۔", "Apne baare mein, taleem aur tajrubay se aagah karein."),
                ConversionSentence(2, "I hold a degree in Computer Science with four years of industry work.", "میں نے کمپیوٹر سائنس میں ڈگری اور چار سال عملی کام کیا ہے۔", "Mein ne Computer Science mein degree aur 4 saal kaam kiya hai."),
                ConversionSentence(3, "What do you consider your greatest professional strength and asset?", "آپ کے نزدیک آپ کی سب سے بڑی پیشہ ورانہ صلاحیت کیا ہے؟", "Aap ke nazdeek aap ki sab se barri salahiyat kya hai?"),
                ConversionSentence(4, "My core strength is solving complex problems under tight deadlines.", "میری سب سے بڑی خوبی سخت ڈیڈ لائنز میں پیچیدہ مسائل حل کرنا ہے۔", "Meri khoobi deadlines mein masail hal karna hai."),
                ConversionSentence(5, "How do you handle constructive criticism and performance reviews?", "آپ اصلاحی مشوروں اور کارکردگی کے جائزے کو کیسے لیتے ہیں؟", "Aap tanqeed aur performance review ko kaisay letay hain?"),
                ConversionSentence(6, "I view constructive feedback as an invaluable pathway to growth.", "میں اصلاحی رائے کو اپنی ذاتی ترقی کا بہترین موقع سمجھتا ہوں۔", "Mein feedback ko apni behtari ka mauqa samajhta hoon."),
                ConversionSentence(7, "Why are you passionate about joining our multinational organization?", "آپ ہمارے بین الاقوامی ادارے میں کام کرنے کے لیے کیوں پرجوش ہیں؟", "Aap hamare idaray mein kaam karne ke liye kyun purjosh hain?"),
                ConversionSentence(8, "I admire your company's innovative culture and commitment to excellence.", "میں آپ کی کمپنی کی جدید سوچ اور اعلیٰ معیار کا معترف ہوں۔", "Mein company ki jadeed soch aur meyaar ka motarif hoon."),
                ConversionSentence(9, "Describe a challenging project you successfully delivered as a team.", "کسی ایسے مشکل پروجیکٹ کا ذکر کریں جو آپ نے ٹیم کے ساتھ مکمل کیا۔", "Kisi aisay project ka zikr karein jo team ke sath kiya."),
                ConversionSentence(10, "We unified cross-functional teams to launch the product on schedule.", "ہم نے مختلف ٹیموں کو جوڑ کر پروڈکٹ کو وقت پر لانچ کیا۔", "Hum ne teams ko mila kar product waqt par launch kiya."),
                ConversionSentence(11, "What are your salary expectations for this senior managerial role?", "اس سینیئر مینیجر کے عہدے کے لیے آپ کی تنخواہ کی کیا توقعات ہیں؟", "Is ohday ke liye aap ki salary ki kya tawaqqoaat hain?"),
                ConversionSentence(12, "I am seeking a competitive package aligned with industry standards.", "میں مارکیٹ کے معیار اور اپنی مہارت کے مطابق پیکیج کا خواہشمند ہوں۔", "Mein market meyaar ke mutabiq package chahta hoon."),
                ConversionSentence(13, "Where do you see yourself professionally five years from now?", "آپ اگلے پانچ سالوں میں خود کو کس پیشہ ورانہ مقام پر دیکھتے ہیں؟", "Aap aglay 5 saalon mein khud ko kahan dekhtay hain?"),
                ConversionSentence(14, "I aim to lead strategic engineering initiatives and mentor young talent.", "میں اہم تزویراتی منصوبوں کی قیادت اور نئے ٹیلنٹ کی رہنمائی چاہتا ہوں۔", "Mein strategic projects ki qayadat chahta hoon."),
                ConversionSentence(15, "Do you have any questions for us regarding the role or company?", "کیا آپ کا اس عہدے یا کمپنی کے بارے میں ہم سے کوئی سوال ہے؟", "Kya aap ka is ohday ya company ke baare mein koi sawal hai?"),
                ConversionSentence(16, "Could you describe the typical career advancement path in this team?", "کیا آپ اس ٹیم میں ترقی کے مواقع کے بارے میں بتا سکتے ہیں؟", "Kya aap team mein taraqi ke raston ke baare mein bata saktay hain?"),
                ConversionSentence(17, "Dress in sharp, professional business formal attire for the interview.", "انٹرویو کے لیے صاف ستھرا اور باوقار رسمی لباس پہنیں۔", "Interview ke liye saaf suthra aur formal libaas pehnein."),
                ConversionSentence(18, "Arrive fifteen minutes prior to the scheduled interview appointment.", "انٹرویو کے مقررہ وقت سے پندرہ منٹ پہلے دفتر پہنچیں۔", "Interview ke waqt se 15 minute pehle pohanchein."),
                ConversionSentence(19, "Maintain confident body posture, a warm smile, and a firm handshake.", "پراعتماد انداز، مسکراہٹ اور گرمجوشی سے سلام کریں۔", "Pur-aitemad andaaz aur muskurahat se salam karein."),
                ConversionSentence(20, "Send a thoughtful thank-you email within twenty-four hours after interview.", "انٹرویو کے بعد چوبیس گھنٹے کے اندر شائستہ تشکر کی ای میل بھیجیں۔", "Interview ke baad shukriya ki email bhejein."),
                ConversionSentence(21, "Highlight your measurable accomplishments using specific data and metrics.", "اپنی کامیابیوں کو اعداد و شمار اور ٹھوس نتائج کے ساتھ بیان کریں۔", "Apni kamyabiyon ko aadaad-o-shumaar ke sath bayan karein."),
                ConversionSentence(22, "Showcase your adaptability in embracing new technologies quickly.", "نئی ٹیکنالوجیز کو تیزی سے سیکھنے کی صلاحیت کو نمایاں کریں۔", "Nayi technologies taizi se seekhnay ki salahiyat dikhayein."),
                ConversionSentence(23, "Continuous self-learning is the key to thriving in modern careers.", "مسلسل نیا علم سیکھنا جدید کیریئر میں کامیابی کی کلید ہے۔", "Musalsal seekhna jadeed career mein kamyabi ki chaabi hai."),
                ConversionSentence(24, "Never speak negatively about previous employers or colleagues.", "اپنے پرانے ادارے یا ساتھیوں کے بارے میں منفی باتیں کبھی نہ کریں۔", "Puranay idaray ke baare mein manfi baatein na karein."),
                ConversionSentence(25, "Demonstrate leadership by taking ownership of challenging initiatives.", "مشکل کاموں کی خود ذمہ داری لے کر اپنی قیادت کا ثبوت دیں۔", "Mushkil kamon ki zimmedari le kar qayadat dikhayein."),
                ConversionSentence(26, "Research the company's recent news, products, and mission beforehand.", "انٹرویو سے پہلے کمپنی کی مصنوعات اور مشن کے بارے میں معلومات لیں۔", "Company ke mission ke baare mein pehle se jaaney."),
                ConversionSentence(27, "Practice behavioral interview questions using the STAR framework.", "اسٹار تکنیک کے تحت صورتحال، عمل اور نتائج کے مطابق مشق کریں۔", "STAR framework ke mutabiq interview ki mashq karein."),
                ConversionSentence(28, "Explain how your expertise directly benefits the employer's bottom line.", "بتائیں کہ آپ کا ہنر ادارے کو کس طرح براہ راست فائدہ دے گا۔", "Batayein ke aap ka hunar idaray ko kaisay faida dega."),
                ConversionSentence(29, "Confidence stems from rigorous preparation and authentic self-belief.", "اعتماد بھرپور تیاری اور اپنی ذات پر سچے بھروسے سے آتا ہے۔", "Aitemad bharpoor tayari aur khud par bharosay se aata hai."),
                ConversionSentence(30, "Every interview is an opportunity to learn, network, and grow.", "ہر انٹرویو سیکھنے، روابط بڑھانے اور آگے بڑھنے کا موقع ہے۔", "Har interview seekhnay aur aagay barhnay ka mauqa hai."),
                ConversionSentence(31, "Negotiate employment contracts with poise, clarity, and professionalism.", "ملازمت کے معاہدے پر وقار اور پیشہ ورانہ انداز سے بات چیت کریں۔", "Job contract par waqaar aur clarity se baat karein."),
                ConversionSentence(32, "Highlight certifications from accredited international institutions.", "معتبر بین الاقوامی اداروں سے حاصل کردہ سرٹیفکیٹس کا ذکر کریں۔", "Mo'tabar idaron ke certificates ka zikr karein."),
                ConversionSentence(33, "Show how you foster collaboration and harmony within diverse teams.", "دکھائیں کہ آپ ٹیم میں اتحاد اور باہمی تعاون کو کیسے فروغ دیتے ہیں۔", "Dikhayein ke aap team mein ittehad kaisay banatay hain."),
                ConversionSentence(34, "A growth mindset transforms workplace challenges into career leaps.", "مثبت سوچ کام کے چیلنجز کو ترقی کی سیڑھی میں بدل دیتی ہے۔", "Musbat soch challenges ko taraqi ki seerhi banati hai."),
                ConversionSentence(35, "Bring printed copies of your updated resume in a neat leather folder.", "اپنے سی وی کی پرنٹ شدہ کاپیاں صاف فولڈر میں ساتھ رکھیں۔", "CV ki printed copies saaf folder mein sath rakhein."),
                ConversionSentence(36, "Answer questions directly with clarity, conciseness, and conviction.", "سوالات کے سیدھے، جامع اور پر اعتماد جوابات دیں۔", "Sawalat ke seedhay, mukhtasir aur pur-aitemad jawab dein."),
                ConversionSentence(37, "Speak about your failures in terms of the valuable lessons learned.", "اپنی پرانی ناکامیوں کو سیکھے گئے اہم اسباق کے طور پر پیش کریں۔", "Na-kamyabiyon ko seekhay gaye sabaq ke tor par pesh karein."),
                ConversionSentence(38, "Express genuine enthusiasm for the company's long-term vision.", "کمپنی کے طویل مدتی وژن کے لیے اپنے سچے جذبے کا اظہار کریں۔", "Company ke vision ke liye apne jazbay ka izhaar karein."),
                ConversionSentence(39, "Maintain professional composure even during intense stress interviews.", "دباؤ والے مشکل سوالات کے دوران بھی اپنے اعصاب پر قابو رکھیں۔", "Dabao walay sawalat mein bhi pursukoon rahein."),
                ConversionSentence(40, "Your unique combination of skills, attitude, and ethics is your edge.", "آپ کا ہنر، مثبت رویہ اور اخلاق ہی آپ کی اصل طاقت ہے۔", "Aap ka hunar, rawaiya aur ikhlaaq aap ki taaqat hai."),
                ConversionSentence(41, "Follow up politely if you haven't received feedback within a week.", "اگر ایک ہفتے میں جواب نہ آئے تو شائستگی سے فالو اپ لیں۔", "Agar aik haftay mein jawab na aaye to follow up lein."),
                ConversionSentence(42, "Keep your resume concise, tailored, and strictly error-free.", "اپنا سی وی مختصر، متعلقہ اور غلطیوں سے پاک رکھیں۔", "Apna CV mukhtasir aur ghaltiyon se paak rakhein."),
                ConversionSentence(43, "Mentorship accelerates your professional trajectory exponentially.", "کسی اچھے استاد کی رہنمائی کیریئر کو تیزی سے آگے بڑھاتی ہے۔", "Kisi ustaad ki rehnumai career ko taizi se barhati hai."),
                ConversionSentence(44, "Workplace ethics and reliability earn lifelong professional loyalty.", "دیانت داری اور بھروسہ مندی کیریئر میں ہمیشہ عزت دلاتی ہے۔", "Dyanat-dari career mein hamesha izzat dilati hai."),
                ConversionSentence(45, "Stay curious, hungry for knowledge, and open to continuous reinvention.", "ہمیشہ نیا علم حاصل کرنے کے لیے تیار اور متجسس رہیں۔", "Hamesha naya ilm seekhnay ke liye tayar rahein."),
                ConversionSentence(46, "Celebrate every job offer with gratitude and humility.", "کسی بھی ملازمت کی پیشکش پر عاجزی اور شکر گزاری کا مظاہرہ کریں۔", "Job offer par aajzi aur shukr ka izhaar karein."),
                ConversionSentence(47, "Hard work paired with high integrity guarantees ultimate triumph.", "سچی محنت اور دیانت داری ہمیشہ شاندار کامیابی دلاتی ہے۔", "Mehnat aur dyanat-dari hamesha kamyabi dilati hai."),
                ConversionSentence(48, "You have what it takes to excel; step forward with unwavering courage.", "آپ میں آگے بڑھنے کی پوری صلاحیت ہے؛ ہمت کے ساتھ قدم بڑھائیں۔", "Aap mein aagay barhnay ki poori salahiyat hai."),
                ConversionSentence(49, "Thank you for considering my application for this distinguished role.", "اس معزز عہدے کے لیے میری درخواست پر غور کرنے کا بہت شکریہ۔", "Is ohday ke liye meri darkhwast par ghaur karne ka shukriya."),
                ConversionSentence(50, "May your career be blessed with limitless success, leadership, and joy!", "اللہ تعالیٰ آپ کے کیریئر کو غیر معمولی ترقی اور برکتوں سے نوازے!", "Allah Ta'ala aap ke career ko taraqi aur barkat ata farmaye!")
            )),
            // 48. Customer Service & Client Care (50 Sentences)
            ConversionTopic(48, "Customer Service & Client Care", "گاہکوں کی خدمت اور رہنمائی", "support_agent", "Assistance, refunds, empathy, issue resolution, and polite care.", listOf(
                ConversionSentence(1, "Thank you for contacting our customer support team; how may I help?", "ہماری کسٹمر سپورٹ ٹیم سے رابطہ کرنے کا شکریہ؛ میں کیا خدمت کروں؟", "Customer support se rabta karne ka shukriya; mein kya madad karoon?"),
                ConversionSentence(2, "I deeply apologize for the inconvenience and delay you experienced.", "آپ کو پیش آنے والی زحمت اور تاخیر کے لیے میں معذرت خواہ ہوں۔", "Aap ko paish aanay wali takleef ke liye mein maazrat chahta hoon."),
                ConversionSentence(3, "Please allow me a moment to review your order details on system.", "مجھے سسٹم پر آپ کے آرڈر کی تفصیلات دیکھنے کے لیے ایک لمحہ دیں۔", "Mujhe system par order ki tafseelaat dekhnay ke liye waqt dein."),
                ConversionSentence(4, "I understand your frustration completely; let me resolve this immediately.", "میں آپ کی پریشانی سمجھتا ہوں؛ آئیے میں اسے فوری حل کرتا ہوں۔", "Mein aap ki pareshani samajhta hoon; fauri hal karta hoon."),
                ConversionSentence(5, "We will dispatch a free replacement parcel to your address today.", "ہم آج ہی آپ کے پتے پر مفت متبادل پارسل روانہ کر دیں گے۔", "Hum aaj hi aap ke patay par naya parcel rawana kar dein ge."),
                ConversionSentence(6, "Could you please provide your registered phone number or tracking ID?", "کیا آپ اپنا رجسٹرڈ فون نمبر یا ٹریکنگ آئی ڈی بتا سکتے ہیں؟", "Kya aap apna registered phone number ya tracking ID bata saktay hain?"),
                ConversionSentence(7, "Your complete satisfaction is our company's highest priority.", "آپ کا مکمل اطمینان ہمارے ادارے کی اولین ترجیح ہے۔", "Aap ka mukammal itminaan hamari awaleen tarjeeh hai."),
                ConversionSentence(8, "We have processed a full refund directly to your original bank card.", "ہم نے آپ کے کارڈ پر پوری رقم واپس (ریفنڈ) منتقل کر دی ہے۔", "Hum ne aap ke card par poori raqam refund kar di hai."),
                ConversionSentence(9, "Thank you for your valuable feedback; it helps us improve services.", "آپ کی قیمتی رائے کا شکریہ؛ یہ ہماری خدمات کو بہتر بناتی ہے۔", "Aap ki qeemti raye ka shukriya; yeh hamari khidmaat behtar karti hai."),
                ConversionSentence(10, "Treat every customer with utmost empathy, respect, and active care.", "ہر کسٹمر کے ساتھ ہمدردی، عزت اور خلوص کے ساتھ پیش آئیں۔", "Har customer ke sath hamdardi aur izzat se pesh aayein."),
                ConversionSentence(11, "How can we assist you with tracking your international parcel delivery?", "ہم آپ کے بین الاقوامی پارسل کی ٹریکنگ میں کیا مدد کر سکتے ہیں؟", "Hum parcel ki tracking mein kya madad kar saktay hain?"),
                ConversionSentence(12, "Our technical support helpline is available twenty-four hours daily.", "ہماری ٹیکنیکل سپورٹ ہیلپ لائن چوبیس گھنٹے حاضر ہے۔", "Hamari technical support helpline 24 ghantay hazir hai."),
                ConversionSentence(13, "I have escalated your ticket to our senior engineering supervisor.", "میں نے آپ کی شکایت سینیئر سپروائزر کو فارورڈ کر دی ہے۔", "Mein ne aap ki shikayat senior supervisor ko bhej di hai."),
                ConversionSentence(14, "You will receive an SMS confirmation update within two hours.", "آپ کو دو گھنٹے کے اندر تصدیقی ایس ایم ایس مل جائے گا۔", "Aap ko 2 ghantay mein SMS update mil jaye ga."),
                ConversionSentence(15, "We appreciate your patience while we investigate this system issue.", "اس خرابی کی جانچ کے دوران آپ کے صبر کا بے حد شکریہ۔", "Is kharabi ki jaanch ke dauran aap ke sabr ka shukriya."),
                ConversionSentence(16, "Is there anything else I can assist you with this afternoon?", "کیا میں آج دوپہر کسی اور معاملے میں بھی آپ کی مدد کر سکتا ہوں؟", "Kya mein kisi aur maamlay mein bhi aap ki madad kar sakta hoon?"),
                ConversionSentence(17, "A satisfied customer is the greatest ambassador for any brand.", "ایک مطمئن گاہک ادارے کا سب سے بڑا سفیر ہوتا ہے۔", "Aik mutmain customer idaray ka sab se barra safeer hota hai."),
                ConversionSentence(18, "Listening actively without interrupting calms an upset caller.", "بغیر ٹوکے بات سننا ناراض کسٹمر کا غصہ ٹھنڈا کر دیتا ہے۔", "Baghair tookay baat sunna customer ka ghussa thanda karta hai."),
                ConversionSentence(19, "Never argue with a customer; focus on finding constructive solutions.", "کسٹمر سے بحث نہ کریں بلکہ مسئلے کے فوری حل پر توجہ دیں۔", "Customer se behas na karein balkay hal par tawajjo dein."),
                ConversionSentence(20, "Clear, polite communication turns dissatisfied users into loyal fans.", "شائستہ بات چیت ناراض گاہک کو مستقل وفادار بنا دیتی ہے۔", "Shaista baat cheet naraz gahak ko wafadar bana deti hai."),
                ConversionSentence(21, "Could you please fill out our brief 1-minute satisfaction survey?", "کیا آپ ہماری سروس کے بارے میں ایک منٹ کا فیڈ بیک دے سکتے ہیں؟", "Kya aap service ke baare mein aik minute ka feedback dein ge?"),
                ConversionSentence(22, "We offer a 30-day money-back guarantee with no questions asked.", "ہم تیس دن کی بلامشروط رقم واپسی کی ضمانت دیتے ہیں۔", "Hum 30 din ki bila-mashroot raqam wapsi ki guarantee detay hain."),
                ConversionSentence(23, "Your complaint has been successfully resolved; thank you for patience.", "آپ کا مسئلہ حل ہو گیا ہے؛ صبر سے کام لینے کا شکریہ۔", "Aap ka masla hal ho gaya hai; sabr ka shukriya."),
                ConversionSentence(24, "We value your continuous loyalty and patronship across the years.", "برسوں سے ہمارے ساتھ جڑے رہنے پر ہم آپ کے شکر گزار ہیں۔", "Saalon se sath jurray rehnay par hum aap ke shukr-guzar hain."),
                ConversionSentence(25, "Customer service is an attitude of heartfelt hospitality and care.", "کسٹمر کی خدمت دراصل دل سے کی جانے والی مہمان نوازی ہے۔", "Customer service dar-asal dil se ki jaanay wali khidmat hai."),
                ConversionSentence(26, "Always follow through on the promises made during support calls.", "کال کے دوران کیے گئے تمام وعدوں کو لازمی پورا کریں۔", "Call ke dauran kiye gaye tamam wadon ko poora karein."),
                ConversionSentence(27, "We have credited promotional reward points to your app wallet.", "ہم نے آپ کے والٹ میں اضافی انعامی پوائنٹس ڈال دیے ہیں۔", "Hum ne aap ke wallet mein reward points daal diye hain."),
                ConversionSentence(28, "Keep your voice calm, reassuring, and professional at all times.", "اپنی آواز کو ہمیشہ پرسکون، تسلی بخش اور باوقار رکھیں۔", "Apni aawaz ko hamesha pursukoon aur shaista rakhein."),
                ConversionSentence(29, "Empathetic customer service creates lifelong human connections.", "ہمدردانہ رویہ گاہکوں کے ساتھ زندگی بھر کے رشتے بناتا ہے۔", "Hamdardana rawaiya lifelong connections banata hai."),
                ConversionSentence(30, "Thank you for choosing our services; have a magnificent day!", "ہماری سروس کا انتخاب کرنے کا شکریہ؛ آپ کا دن خوشگوار گزرے!", "Hamari service chun-nay ka shukriya; aap ka din acha guzray!"),
                ConversionSentence(31, "How can I update my billing address on the customer portal?", "میں کسٹمر پورٹل پر اپنا بلنگ کا پتہ کیسے تبدیل کروں؟", "Mein portal par apna billing address kaisay badloon?"),
