                ConversionSentence(22, "Solid-state batteries charge vehicles in minutes and prevent fire hazards.", "جدید سالڈ اسٹیٹ بیٹریاں گاڑیوں کو چند منٹ میں چارج کرتی ہیں۔", "Solid state batteries gaariyon ko taizi se charge karti hain."),
                ConversionSentence(23, "Machine learning models predict weather patterns with high precision.", "مشین لرننگ ماڈلز موسم کی درست پیش گوئی کرتے ہیں۔", "Machine learning mausam ki sahi paish-goi karti hai."),
                ConversionSentence(24, "Human curiosity to explore the unknown is our greatest superpower.", "نامعلوم کو جاننے کا انسانی تجسس ہماری سب سے بڑی طاقت ہے۔", "Na-maloom ko jaannay ka tajassus insani taaqat hai."),
                ConversionSentence(25, "Gravitational waves confirm Einstein's general theory of relativity.", "کشش ثقل کی لہریں آئنسٹائن کے نظریے کی تصدیق کرتی ہیں۔", "Gravitational waves Einstein ke nazriye ko sabit karti hain."),
                ConversionSentence(26, "Biodegradable mushroom mycelium packaging replaces toxic Styrofoam.", "کھمبی سے بنے پیکٹس زہریلے تھرموپول کا ماحول دوست متبادل ہیں۔", "Mushroom packaging plastic ka behtareen mutabadil hai."),
                ConversionSentence(27, "Wireless power transmission will charge devices across rooms without cords.", "بغیر تاروں کے ہوا کے ذریعے برقی توانائی منتقل کرنے پر کام جاری ہے۔", "Baghair taron ke bijli muntaqil karne par kaam jari hai."),
