                ConversionSentence(40, "Knowledge is a radiant torch that dispels darkness of ignorance.", "علم ایک روشن مشعل ہے جو جہالت کے اندھیروں کو مٹاتی ہے۔", "Ilm aik roshan mash'al hai jo andheron ko mitati hai."),
                ConversionSentence(41, "Microscopic nanobots will deliver chemotherapy directly to cancer cells.", "ننھے روبوٹس کینسر کے خلیات تک براہ راست دوا پہنچائیں گے۔", "Microscopic robots cancer cells tak dawa pohanchayein ge."),
                ConversionSentence(42, "Hydrogen fuel cell buses emit nothing but pure drinkable water vapor.", "ہائیڈروجن فیول بسیں دھوئیں کے بجائے صرف پانی کا بخار چھوڑتی ہیں۔", "Hydrogen buses sirf paani ka steam nikaalti hain."),
                ConversionSentence(43, "Augmented reality smart glasses overlay rich digital info onto reality.", "اسمارٹ چشمے حقیقی دنیا پر ڈیجیٹل معلومات دکھاتے ہیں۔", "Smart glasses haqeeqi dunya par data dikhati hain."),
                ConversionSentence(44, "Deep sea submersibles explore the deepest oceanic trenches on Earth.", "گہرے سمندر کی آبدوزیں زیرِ آب نایاب حیات کی کھوج لگاتی ہیں۔", "Submarines samandar ki gehraiyon ki tehqeeq karti hain."),
                ConversionSentence(45, "Solar powered desalination provides freshwater to arid desert regions.", "شمسی توانائی سے صحرائی علاقوں میں میٹھا پانی فراہم کیا جا رہا ہے۔", "Solar energy se sehrai ilaaqon mein paani diya ja raha hai."),
                ConversionSentence(46, "Science teaches us wonder, humility, curiosity, and relentless learning.", "سائنس ہمیں حیرت، عاجزی اور مسلسل سیکھنے کا جذبہ سکھاتی ہے۔", "Science humein aajzi aur seekhnay ka jazba sikhati hai."),
