                ConversionSentence(6, "Help neighbors and community members in times of hardship silently.", "مشکل کے وقت پڑوسیوں اور مستحقین کی خاموشی سے مدد کریں۔", "Mushkil ke waqt parosiyon ki khamoshi se madad karein."),
                ConversionSentence(7, "Forgiving those who hurt you liberates your own heart from bitterness.", "تکلیف دینے والوں کو معاف کر دینا دل کو نفرت سے آزاد کرتا ہے۔", "Takleef denay walon ko maaf karna dil ko azaad karta hai."),
                ConversionSentence(8, "Patience (Sabr) through trials turns bitter suffering into radiant gold.", "آزمائشوں پر صبر کرنا دکھ کو کندن اور نیکی میں بدل دیتا ہے۔", "Aazmaishon par sabr karna dukh ko bhalai mein badalta hai."),
                ConversionSentence(9, "Cleanliness in personal hygiene and surroundings is half of faith.", "اپنے جسم اور ماحول کی صفائی نصف ایمان کا درجہ رکھتی ہے۔", "Apne jism aur mahaul ki safaai nisf imaan hai."),
                ConversionSentence(10, "Live with purpose, serve humanity, and leave a legacy of blessings.", "بامقصد زندگی گزاریں، انسانیت کی خدمت کریں اور اچھی یادیں چھوڑ جائیں۔", "Ba-maqsad zindagi guzarein aur khidmat karein."),
                ConversionSentence(11, "How do we cultivate moral resilience in our daily family lives?", "ہم اپنی روزمرہ خاندانی زندگی میں اخلاقی اقدار کیسے پیدا کریں؟", "Hum rozmarrah zindagi mein ikhlaaqi aqdaar kaisay banayein?"),
                ConversionSentence(12, "Practice self-accountability before judging or blaming others.", "دوسروں پر تنقید کرنے سے پہلے اپنا محاسبہ کرنے کی عادت ڈالیں۔", "Doosron par tanqeed se pehle apna jaiza lein."),
                ConversionSentence(13, "Gratitude turns ordinary daily meals into rich joyous feasts.", "شکر گزاری سادہ کھانے کو بھی پرمسرت ضیافت بنا دیتی ہے۔", "Shukr-guzari saada khanay ko nemat bana deti hai."),
                ConversionSentence(14, "Never engage in backbiting, gossip, or character assassination.", "غیبت، چغلی اور کسی کی عزت اچھالنے سے ہمیشہ بچیں۔", "Gheebat, chughli aur bohtaan se hamesha bachein."),
                ConversionSentence(15, "Speak truth even when it feels inconvenient or personally difficult.", "سچی بات کہیں چاہے وہ آپ کے اپنے لیے کڑوی ہی کیوں نہ ہو۔", "Sachi baat kahein chahay woh karwi hi kyun na ho."),
                ConversionSentence(16, "Respect the dignity of hard labor, whether a sweeper or executive.", "محنت کش کی عزت کریں چاہے وہ جھاڑو دینے والا ہو یا افسر۔", "Mehnat-kash ki izzat karein chahay koi bhi ho."),
                ConversionSentence(17, "Feed the hungry, comfort the orphan, and shelter the destitute.", "بھوکوں کو کھانا کھلائیں، یتیموں کا سہارا بنیں اور بے سہاروں کو پناہ دیں۔", "Bhookon ko khana khilayein aur yateemon ka sahara banein."),
                ConversionSentence(18, "A good deed done in secret shines brighter than worldly gold.", "تنہائی میں کی گئی خاموش نیکی دنیا کی تمام دولت سے افضل ہے۔", "Tanhai mein ki gayi naiki dunya ki daulat se behtar hai."),
                ConversionSentence(19, "Guard your tongue; words can either heal hearts or break souls.", "اپنی زبان کی حفاظت کریں؛ الفاظ دل جوڑتے بھی ہیں اور توڑتے بھی۔", "Apni zaban ki hifazat karein; alfaaz dil tortay bhi hain."),
                ConversionSentence(20, "Peace of conscience is the sweetest pillow to sleep upon at night.", "مطمئن ضمیر رات کو سونے کے لیے دنیا کا سب سے پرسکون تکیہ ہے۔", "Mutmain zameer sonay ke liye sab se pursukoon takiya hai."),
                ConversionSentence(21, "Show utmost respect to teachers and mentors who guide your mind.", "اپنے اساتذہ اور رہنمائی کرنے والوں کا دل سے ادب و احترام کریں۔", "Apne asatiza aur ustaadon ka adab karein."),
                ConversionSentence(22, "Be content with what you have while striving honorably for better.", "جو میسر ہے اس پر راضی رہیں اور حلال طریقے سے بہتری کی کوشش کریں۔", "Jo mayassar hai us par raazi rahein aur halal koshish karein."),
                ConversionSentence(23, "Greed is a bottomless well that never fills; contentment is wealth.", "لالچ ایک ایسا کنواں ہے جو کبھی نہیں بھرتا؛ قناعت ہی اصل دولت ہے۔", "Laalach kabhi nahi bharta; qana'at hi asal daulat hai."),
                ConversionSentence(24, "Stand firmly with the oppressed against injustice everywhere.", "ہر جگہ ظلم کے خلاف اور مظلوم کے حق میں ڈٹ کر کھڑے ہوں۔", "Zulm ke khilaf aur mazloom ke haq mein kharray hon."),
                ConversionSentence(25, "Kindness is a universal language that the deaf hear and blind see.", "شفقت وہ زبان ہے جو بہرے بھی سنتے ہیں اور اندھے بھی دیکھتے ہیں۔", "Shafqat aisi zaban hai jo sab samajhtay hain."),
                ConversionSentence(26, "Treat your guests with generous hospitality, warmth, and joy.", "مہمانوں کی خدمت کھلے دل، مسکراہٹ اور خلوص کے ساتھ کریں۔", "Mehmanon ki khidmat khulay dil aur muskurahat se karein."),
                ConversionSentence(27, "Keep your heart free from poisonous jealousy, envy, and malice.", "اپنے دل کو حسد، بغض اور کینے کے زہر سے ہمیشہ پاک رکھیں۔", "Apne dil ko hasad aur keena se paak rakhein."),
                ConversionSentence(28, "Small consistent acts of charity avert difficulties and trials.", "روزانہ کا چھوٹا سا صدقہ بھی بڑی مصیبتوں کو ٹال دیتا ہے۔", "Rozana ka sadqa barri museebaton ko taalta hai."),
                ConversionSentence(29, "A noble character leaves a fragrant memory that never fades.", "اعلیٰ کردار ایسی خوشبو چھوڑتا ہے جو کبھی ماند نہیں پڑتی۔", "Aala kirdaar aisi khushboo chhorta hai jo rehti hai."),
                ConversionSentence(30, "Life is a brief journey; make every step count for goodness.", "زندگی ایک مختصر سفر ہے؛ ہر قدم نیکی اور بھلائی کے لیے اٹھائیں۔", "Zindagi mukhtasir safar hai; naiki ka rasta apnayein."),
                ConversionSentence(31, "Give priority to resolving broken ties with estranged friends.", "ناراض دوستوں اور رشتے داروں سے صلح کرنے میں پہل کریں۔", "Naraaz doston se sulah karne mein pehal karein."),
                ConversionSentence(32, "Honest earnings bring enduring tranquility and barakah to home.", "حلال کمائی گھر میں دائمی سکون اور برکت لے کر آتی ہے۔", "Halaal kamai ghar mein sukoon aur barkat laati hai."),
                ConversionSentence(33, "Never look down upon anyone; circumstances can shift in an instant.", "کسی کو حقیر نہ سمجھیں؛ حالات بدلتے دیر نہیں لگتی۔", "Kisi ko haqeer na samjhein; halaat badal saktay hain."),
                ConversionSentence(34, "Be a beacon of hope and encouragement to someone in despair.", "مایوس انسان کے لیے امید اور حوصلے کی کرن بنیں۔", "Mayoos insaan ke liye umeed aur hauslay ki kiran banein."),
                ConversionSentence(35, "Protect the trust (Amanah) placed in you with utmost loyalty.", "آپ کو دی گئی امانت کی حفاظت پوری دیانت داری سے کریں۔", "Amanat ki hifazat poori dyanat-dari se karein."),
                ConversionSentence(36, "A calm temper diffuses anger before it ignites destruction.", "ٹھنڈا مزاج غصے کی آگ کو بھڑکنے سے پہلے بجھا دیتا ہے۔", "Thanda mizaj ghussay ki aag ko bujha deta hai."),
                ConversionSentence(37, "Teach children that true nobility lies in moral virtue, not status.", "بچوں کو سکھائیں کہ اصل بڑائی عہدے میں نہیں بلکہ اچھے اخلاق میں ہے۔", "Bachon ko sikhayein ke asal barrai ikhlaaq mein hai."),
                ConversionSentence(38, "Every morning is a divine opportunity to begin anew with purity.", "ہر نئی صبح نیکی کی طرف لوٹنے اور نیا آغاز کرنے کا موقع ہے۔", "Har nayi subah naiki ka naya aaghaz karne ka mauqa hai."),
                ConversionSentence(39, "Spread greeting of Salam (peace) to those you know and know not.", "سلامتی اور امن کا پیغام ہر جانے اور انجانے شخص کو دیں۔", "Salamti aur aman ka paigham sab ko dein."),
                ConversionSentence(40, "Cultivate empathy: feel the unspoken sorrow in other people's eyes.", "دوسروں کے چہروں پر پوشیدہ دکھ کو محسوس کرنا سیکھیں۔", "Doosron ke chehron par dukh ko mehsoos karein."),
                ConversionSentence(41, "Praise the creator for all countless blessings we take for granted.", "ہر اس نعمت پر خالق کا شکر کریں جس کے ہم عادی ہو چکے ہیں۔", "Har nemat par Khaliq ka shukr ada karein."),
                ConversionSentence(42, "Live lightly on Earth, tread gently, and speak lovingly to all.", "زمین پر عاجزی سے چلیں اور ہر ایک سے پیار سے بات کریں۔", "Zameen par aajzi se chalein aur pyar se baat karein."),
                ConversionSentence(43, "The best amongst people is the one who benefits humanity most.", "لوگوں میں سب سے بہترین وہ ہے جو انسانیت کو سب سے زیادہ نفع دے۔", "Logon mein behtareen woh hai jo sab ko faida de."),
                ConversionSentence(44, "A sincere heart is the most precious sanctuary in existence.", "ایک مخلص اور صاف دل دنیا کی سب سے خوبصورت پناہ گاہ ہے۔", "Aik mukhlis aur saaf dil sab se khubsurat hai."),
                ConversionSentence(45, "Patience and prayers are your strongest companions through trials.", "صبر اور دعا آزمائش کے وقت آپ کے سب سے مضبوط ساتھی ہیں۔", "Sabr aur dua aazmaish mein sab se barray saathi hain."),
                ConversionSentence(46, "Fill your days with deeds that will bring peace at twilight of life.", "اپنی زندگی کو ایسے کاموں سے سجائیں جو آخری وقت سکون دیں۔", "Apni zindagi ko aisi naiki se sajayein jo sukoon de."),
                ConversionSentence(47, "May your moral character shine as an inspiring beacon for all!", "اللہ کرے آپ کا کردار دوسروں کے لیے مشعلِ راہ بن جائے!", "Allah karay aap ka kirdaar doosron ke liye misaal banay!"),
                ConversionSentence(48, "Thank you for walking the noble path of truth, mercy, and compassion.", "سچائی، رحمت اور محبت کا راستہ اپنانے پر آپ کو سلام۔", "Sachai aur mohabbat ka rasta apnanay par aap ko salam."),
                ConversionSentence(49, "May divine grace encompass you, your loved ones, and all creation!", "اللہ تعالیٰ کا فضل اور رحمت آپ پر اور آپ کے پیاروں پر ہمیشہ سایہ فگن رہے!", "Allah Ta'ala ka fazl aur rehmat aap par hamesha rahay!"),
                ConversionSentence(50, "May peace, barakah, love, and light abide with you forever!", "اللہ کرے امن، برکت، محبت اور نور ہمیشہ آپ کے ساتھ رہے!", "Allah karay aman, barkat aur noor hamesha aap ke sath rahay!")
            ))
        )
    }
}
